    if sum(A) % K != 0:
        return "NO"
    target_sum = sum(A) // K
    max_seen = min_seen = max_seen_index = now = 0
    for i in range(N):
        if i < min_seen:
            now += A[i]
            now += target_sum - now
            if now > max_seen:
                max_seen = now
                max_seen_index = i
        elif i <= min_seen + K - 1:
            now += A[i]
            now += target_sum - now
        else:
            now += A[i] - A[i - min_seen]
            now -= A[i - max_seen]
            if now > max_seen:
