        graph[v].append((w, u))

    def bfs(start, color):
        queue = deque([(start, 0, color)])
        visited = {start: [color]}
        shortest = 0
        while queue:
            node, depth, original_color = queue.popleft()
            if node == -1:
                shortest = max(shortest, depth)
            else:
                visited[node][color] = depth
                for next_node, edge in graph[node]:
                    if (next_node not in visited) or (visited[next_node][not color] > depth + 1):
                        queue.append((next_node, depth + 1, not color))
        return shortest

    color1, color2 = 1, 0
    unreachable_distance1 = bfs(colors[0], color1)
    unreachable_distance2 = bfs(colors[0], color2)

    if max(unreachable_distance1, unreachable_distance2) > x:
        return -1

    current_colors = copy.deepcopy(colors)

    for i in range(n):
        if i > n:
            break
        if current_colors[i]:
