    for i in range(len(d)):
        if d[i] <= x:
            continue
        elif i - d[i] <= d[i] <= i + x or (-1 * d[i] <= x <= 1 * d[i]):
            yield d[i] - int(abs(i - d[i]) == 1 or abs(i - d[i]) <= x)
    return iter([])

def cal_max_size(d, x):
