import sys

def max_area(n, k, vertices):
    # Calculate all possible cuts
    cuts = []
    for i in range(n):
        for j in range(i + 1, n):
            cuts.append((vertices[i][0], vertices[i][1], vertices[j][0], vertices[j][1]))

    # Function to calculate the area of a triangle given its vertices
    def triangle_area(x1, y1, x2, y2, x3, y3):
        return abs(x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2.0

    max_area = 0
    vertex_to_index = {v[1]: i for i, (x, y) in enumerate(vertices)}
    connections = {v[1]: {j for i, (x, y) in enumerate(vertices) if i != j} for j, (x, y) in enumerate(vertices)}

    for i in range(n - 1):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                # Find the cut that includes the current vertex i
                for cut in cuts:
                    if all(v in connections[i] for v in cut):
                        break
                else:
                    continue

                # Find the cut that includes the current vertex j
                for cut in cuts:
                    if all(v in connections[j] for v in cut):
                        break
                else:
                    continue

                # Find the cut that includes the current vertex k
                for cut in cuts:
                    if all(v in connections[k] for v in cut):
                        break
                else:
                    continue

                # Find the cut that forms the triangle with vertices i, j, and k
                for c in cuts:
                    if c != cut and all(v in {j for i, (x, y) in enumerate(vertices) if i != j} for v in c):
                        break
                else:
                    continue

                # Update the maximum area
                max_area = max(max_area, triangle_area(cut[0], cut[1], cut[2], cut[3], vertices[i][0], vertices[i][1]))
                max_area = max(max_area, triangle_area(cut[0], cut[1], cut[2], cut[3], vertices[j][0], vertices[j][1]))
                max_area = max(max_area, triangle_area(cut[0], cut[1], cut[2], cut[3], vertices[k][0], vertices[k][1]))

    # Double the area to consider the problem statement
    return 2 * max_area

