class Graph:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v, c):
        self.adj[u-1].append((v-1, c))
        self.adj[v-1].append((u-1, c))

    def dfs(self, u, visited, min_vals, res, order):
        visited[u] = True
        head = u
        for v, c in self.adj[u]:
            if not visited[v]:
                res.add(c)
                order[c] = len(order)
                self.dfs(v, visited, min_vals, res, order)
                head = self.min_cord(min_vals)[0]
        while order and head != self.min_cord(order)[-1]:
            min_vals[head] = next(iter(self.adj[head]))
            head = self.min_cord(min_vals)[0]
        self.min_vals[head] = -1

    def min_cord(self, min_vals):
        min_v = 0
        for idx, v in enumerate(min_vals):
            if v == min(min_vals):
                min_v = idx
        min_vals[min_v] = -1
        return min_v, min_vals

    def run(self, queries):
        result = []
        visited = [False] * self.n
        order = []
        min_vals = self.max_vals()

        for u, v in queries:
            if not visited[u-1] and not visited[v-1]:
                self.dfs(u-1, visited, min_vals, set(), order)
                self.dfs(v-1, visited, min_vals, set(), order)
            elif not visited[u-1]:
                self.dfs(u-1, visited, min_vals, set([self.max_vals()[u-1]]), order)
            elif not visited[v-1]:
                self.dfs(v-1, visited, min_vals, set([self.max_vals()[v-1]]), order)

            res = []
            if not res:
                min_cord = self.min_cord(min_vals)[0]
                inserted = 0
                while inserted < len(res) and res[inserted] == min_cord:
                    res.pop()
                    inserted += 1 
                inserted = 0
                while not res or res[inserted] == 0 or res[min(0, len(res)-1)] == 0:
                    res.insert(0, ((u-1, self.min_cord(min_vals) if inserted-1 >= 0 else self.max_vals()[u-1]), inserted))
                    inserted += 1
                res.insert(0, ((v-1, self.min_cord(min_vals) if res[0][1] >= 0 else self.max_vals()[v-1]), res[0][1]))
                result.append(inserted)

        return result

