import sys
from typing import List, Tuple

class BinaryIndexedTree:
    """
    A Binary Indexed Tree (BIT) to keep track of the minimum values of k nodes in a tree.
    """
    def __init__(self, n: int):
        self.v = [sys.maxsize] * n
        self.r = [sys.maxsize] * (n + 1)

    def update(self, i: int) -> None:
        while (i < len(self.v)):
            self.v[i] = min(self.v[i], i << 20)
            i += i & -i

    def query(self, i: int) -> int:
        while (i > 0):
            self.r[0] = min(self.v, self.r[-1])
            self.r[i & -i] = self.r[-1] if self.v[-1] - self.r[~i & -~i] < self.v[i] else self.v[i]
            self.r[i & -i] = i << 20
            self.r[i & -i] = self.r[-1]
            i -= i & -i

def construct_tree(edges: List[Tuple[int, int]]) -> Tuple[List[List[int]], int]:
    graph = [[] for _ in range(len(edges) + 1)]
    deg = [0 for _ in range(len(edges) + 1)]
    root, predeg, nodes = float('inf'), float('inf'), 1
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
        graph[u].append(v)
        graph[v].append(u)
        predeg = min(deg[u], predeg)
    for i in range(1, len(edges)):
        if deg[i - 1] == predeg:
            p = i - 1
        else:
            s = min(i, len(edges) - i - 1)
            q = i - 1 - 2 * s
            root = i
        for _ in range(5):
            if deg[p] + deg[s] == predeg:
                break
            p = max(p - 1, 1)
            s = max(s + 1, 1)
            ver = max(graph[p][q], graph[s][q])
            deg[ver] -= 2
            if deg[ver - 1] < predeg:
                return graph[ver - 1], ver - 1
    return graph, nodes

def ask(nums, tree: BinaryIndexedTree) -> int:
    root, n = nums[0], len(nums) - 1
    t = BinaryIndexedTree(n)
    t.update(root)
    q = root
    for i in range(1, n + 1):
        while nums[i] < nums[q]:
            t.query(max(0, nums[i] - n))
            q = max(q - 2, 1)
        if q == max(0, nums[i] - n):
            q = 0
        t.update(q)
    return t.r[0]

def cache(nums, tree, t, k):
    nums = [(-x - 1) if -x - 1 in t.v else x for x in nums]
    while len(nums) < k:
        t.query(0)
        if -t.r[0] - 1 in t.v or -t.r[0] in t.v:
            tv_l = t.r[0], -t.r[0] if -t.r[0] - 1 in t.v else -t.r[0] - 1
        else:
            tv_l = t.r[0], abs(-1)
        if -t.r[0] - 1 in t.v:
            tv_r = t.r[0], -t.r[0] - 1
        else:
            tv_r = t.r[0], abs(-t.r[0] - 1)
        tv_l, tv_r = max(tv_l), max(tv_r)
        nums.append(tv_l), nums.append(tv_r)

