    def minimum(a, b):
        if a is -1:
            return b
        if b is -1:
            return a
        if a < b:
            return a
        return b

    # Build adjacency list
    adjacency_list = [[] for _ in range(n)]
    for u, v, weight in edges:
        adjacency_list[u].append((v, weight))
        adjacency_list[v].append((u, weight))

    minimum_distance = 0
    for vertex in vertices:
        distance = 0
        seen_vertices = set()
        seen_vertices.add(vertex)
        while parent[0] is None:
            distances = {i: float('inf') for i in parent}
            distance_heap = [(0, parent[0])]
            minimum_distance += 1
            while distance_heap:
                distance, current = heappop(distance_heap)
                if current in seen_vertices:
                    continue
                seen_vertices.add(current)
                distances[current] = distance
                for adj, weight in adjacency_list[current]:
                    if adj in seen_vertices:
                        continue
                    heappush(distance_heap, (distances[current] + weight, adj))
        swap_operations = distances[1] - distance_heap[0][0]
        minimum_distance += swap_operations
    return minimum_distance // 2  # We only want the minimum number of swaps, not the total swaps.



