def build_lca_tree(graph, size):
    parent = defaultdict(int)
    depth = defaultdict(int)
    lca = defaultdict(int)
    for u in range(1, size + 1):
        while u != 1:
            depth[u] = depth[u >> 1] + 1
            lca[u] = u >> 1
            u = u >> 1
    tree = {}
    for u in range(1, size + 1):
        tree[u] = []
        for v in graph[u].values():
            if depth[u] > depth[v]:
                tree[u].append(max((lca[u] + u, v)))
    return tree, parent, depth

