import sys

def max_cut_area(n, k, vertices):
    max_area = 0
    cut_segments = []
    for i in range(n):
        for j in range(i + 1, n):
            cut_segments.append((vertices[i], vertices[j]))
    for i in range(n):
        for j in range(i + 1, n - k):
            for m in range(j + 1, n - k + i):
                n_cut_vertices = cut_segments[j].copy()
                for p in range(j + 1, n - k + 1):
                    if n_cut_vertices.count(p) != 2:
                        n_cut_vertices.remove(p)
                    else:
                        n_cut_vertices[p] = 0
                if min([x for _ in (2, n_cut_vertices) for x in _]) > max_area:
                    max_area = min([x for _ in (2, n_cut_vertices) for x in _]) / 2
    return int(max_area * 2)

n, k = map(int, input().split())
vertices = [list(map(int, input().split())) for _ in range(n)]
print(max_cut_area(n, k, vertices))
