def find_repeating_block(s):
    # Check if the last 2 characters are equal, then concatenate s with itself
    if s[-1] == s[-2]:
        return s + s
    return s

def process_input(s):
    while s:
        # Find the shortest repeating substring
        len_s = len(s)
        for i in range(1, len_s // 2 + 1):
            if (len_s % i == 0):
                sub = s[i:].replace(sub, sub[:1])
                if len(sub) < len_s // i:
                    return find_repeating_block(sub)

s = input().strip()
print(process_input(s))
